// Replicate vectorIndexing.js: chunk text + prepare embedding requests
// Uses sentence-aware chunking identical to utils/chunker.js
const CHUNK_SIZE = 500;
const CHUNK_OVERLAP = 50;
const BATCH_SIZE = 20;

function chunkText(text) {
  if (!text || text.trim().length === 0) return [];
  const sentences = text.match(/[^.!?\n]+[.!?\n]*/g) || [text];
  const chunks = [];
  let currentChunk = '';

  for (const sentence of sentences) {
    const trimmed = sentence.trim();
    if (!trimmed) continue;

    if (currentChunk.length + trimmed.length > CHUNK_SIZE && currentChunk.length > 0) {
      chunks.push(currentChunk.trim());
      if (CHUNK_OVERLAP > 0) {
        const overlapText = currentChunk.slice(-CHUNK_OVERLAP);
        currentChunk = overlapText + ' ' + trimmed;
      } else {
        currentChunk = trimmed;
      }
    } else {
      currentChunk += (currentChunk ? ' ' : '') + trimmed;
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
}

const articles = $input.all().map(i => i.json);
const allBatches = [];

for (const article of articles) {
  const textToChunk = article.content || article.summary || '';
  if (textToChunk.length < 50) {
    // Still mark as indexed later, but skip chunking
    allBatches.push({
      json: {
        article_id: article.id,
        skip: true,
        chunks: [],
        texts_for_embedding: [],
        points_metadata: []
      }
    });
    continue;
  }

  const chunks = chunkText(textToChunk);

  // Prepend title to each chunk for better embedding context
  const textsForEmbedding = chunks.map(chunk => `${article.title}\n\n${chunk}`);

  // Build metadata for each chunk
  const pointsMetadata = chunks.map((chunk, idx) => ({
    id: article.id * 10000 + idx,
    chunk_index: idx,
    chunk_text: chunk,
    title: article.title,
    source: article.source,
    category: article.category,
    published_at: article.published_at ? new Date(article.published_at).toISOString() : null,
    url: article.url,
    article_id: article.id
  }));

  // Split into batches of BATCH_SIZE for embedding API
  for (let i = 0; i < textsForEmbedding.length; i += BATCH_SIZE) {
    allBatches.push({
      json: {
        article_id: article.id,
        skip: false,
        texts_for_embedding: textsForEmbedding.slice(i, i + BATCH_SIZE),
        points_metadata: pointsMetadata.slice(i, i + BATCH_SIZE)
      }
    });
  }
}

if (allBatches.length === 0) {
  return [{ json: { message: 'No articles to index', skip_all: true } }];
}

return allBatches;

// Build Qdrant upsert payload from embeddings + metadata
const embeddingResponse = $json;
const batchData = $('Has Chunks to Embed?').first().json;

const vectors = embeddingResponse.data.map(d => d.embedding);
const points = vectors.map((vector, j) => {
  const meta = batchData.points_metadata[j];
  return {
    id: meta.id,
    vector: vector,
    payload: {
      article_id: meta.article_id,
      chunk_index: meta.chunk_index,
      chunk_text: meta.chunk_text,
      title: meta.title,
      source: meta.source,
      category: meta.category,
      published_at: meta.published_at,
      url: meta.url
    }
  };
});

return [{
  json: {
    article_id: batchData.article_id,
    points,
    chunk_count: points.length
  }
}];

// Collect all results and produce summary
const items = $input.all();
let totalChunks = 0;
const articleIds = new Set();

for (const item of items) {
  if (item.json.chunk_count) {
    totalChunks += item.json.chunk_count;
  }
  if (item.json.article_id) {
    articleIds.add(item.json.article_id);
  }
}

return [{
  json: {
    message: `Vector indexing complete. Articles indexed: ${articleIds.size}, Total chunks: ${totalChunks}`,
    articlesIndexed: articleIds.size,
    totalChunks,
    timestamp: new Date().toISOString()
  }
}];
